import'package:flutter/material.dart';import'../models/learner_twin.dart';import'../services/funzi_api.dart';
class MasteryPage extends StatelessWidget{final LearnerTwin twin;const MasteryPage(this.twin,{super.key});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Mastery map',style:Theme.of(c).textTheme.headlineMedium),...twin.skills.map((s)=>Card(child:ListTile(title:Text(s.name),subtitle:LinearProgressIndicator(value:s.mastery),trailing:Text('${(s.mastery*100).round()}%'))))]);}
class ExperiencesPage extends StatefulWidget{final LearnerTwin twin;const ExperiencesPage(this.twin,{super.key});@override State<ExperiencesPage>createState()=>_ExperiencesPageState();}
class _ExperiencesPageState extends State<ExperiencesPage>{String? skill;double minutes=20;Map<String,dynamic>?route,experience;bool busy=false;@override Widget build(BuildContext c){skill??=widget.twin.skills.isEmpty?'':widget.twin.skills.first.id;return ListView(padding:const EdgeInsets.all(20),children:[Text('Adaptive experiences',style:Theme.of(c).textTheme.headlineMedium),DropdownButtonFormField<String>(value:skill,items:widget.twin.skills.map((s)=>DropdownMenuItem(value:s.id,child:Text(s.name))).toList(),onChanged:(v)=>setState(()=>skill=v)),Slider(value:minutes,min:5,max:90,divisions:17,label:'${minutes.round()} min',onChanged:(v)=>setState(()=>minutes=v)),FilledButton(onPressed:busy||skill!.isEmpty?null:()async{setState(()=>busy=true);try{final r=await FunziApi.route(skill!,minutes:minutes.round());final e=await FunziApi.adaptive(skill!,"${r['mode']}");setState((){route=r;experience=e;});}finally{setState(()=>busy=false);}},child:const Text('Recommend experience')),if(route!=null)Card(child:ListTile(title:Text("${route!['mode']}"),subtitle:Text("${route!['reason']}"))),if(experience!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text("${experience!['title']}",style:Theme.of(c).textTheme.titleLarge),Text("${experience!['instructions']}"),...((experience!['steps']as List?)??[]).map((x)=>ListTile(leading:const Icon(Icons.check_circle_outline),title:Text("${x['type']}"),subtitle:Text("${x['prompt']}")))]))) ]);}}
class PracticePage extends StatefulWidget{final LearnerTwin twin;const PracticePage(this.twin,{super.key});@override State<PracticePage>createState()=>_PracticePageState();}
class _PracticePageState extends State<PracticePage>{Object?out;Future<void>go(String kind)async{if(widget.twin.skills.isEmpty)return;final s=[...widget.twin.skills]..sort((a,b)=>a.mastery.compareTo(b.mastery));setState(()=>out='Generating…');final r=kind=='quiz'?await FunziApi.quiz(s.first.id):kind=='cards'?await FunziApi.flashcards(s.first.id):await FunziApi.quests();setState(()=>out=r);}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Practice & quests',style:Theme.of(c).textTheme.headlineMedium),Wrap(spacing:8,children:[FilledButton(onPressed:()=>go('quiz'),child:const Text('Adaptive quiz')),OutlinedButton(onPressed:()=>go('cards'),child:const Text('Flashcards')),OutlinedButton(onPressed:()=>go('quests'),child:const Text('Generate quests'))]),if(out!=null)SelectableText('$out')]);}
class PlanPage extends StatelessWidget{final LearnerTwin twin;const PlanPage(this.twin,{super.key});@override Widget build(BuildContext c){final skills=[...twin.skills]..sort((a,b)=>a.mastery.compareTo(b.mastery));return ListView(padding:const EdgeInsets.all(20),children:[Text('Dynamic plan',style:Theme.of(c).textTheme.headlineMedium),...skills.take(3).map((s)=>Card(child:ListTile(leading:const Icon(Icons.route),title:Text('Practice ${s.name}'),subtitle:Text('${s.mastery<.5?20:15} min · target lowest mastery first'))))]);}}
class TeacherPage extends StatelessWidget{final LearnerTwin twin;const TeacherPage(this.twin,{super.key});@override Widget build(BuildContext c){final x=[...twin.skills]..sort((a,b)=>a.mastery.compareTo(b.mastery));return ListView(padding:const EdgeInsets.all(20),children:[Text('Teacher intervention radar',style:Theme.of(c).textTheme.headlineMedium),...x.take(3).map((s)=>Card(child:ListTile(leading:const Icon(Icons.warning_amber),title:Text(s.name),subtitle:Text('${(s.mastery*100).round()}% mastery · prerequisite repair / targeted evidence'))))]);}}
class ParentPage extends StatelessWidget{final LearnerTwin twin;const ParentPage(this.twin,{super.key});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Parent summary',style:Theme.of(c).textTheme.headlineMedium),const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Support short, consistent practice on the lowest-mastery skills. Parent access remains limited to explicitly linked learners.')))]);}